// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testFuzz_property(uint256 initialVal, uint256 newVal) public {
        initialVal = bound(initialVal, 0, type(uint256).max);
        newVal = bound(newVal, 0, type(uint256).max);

        c.SetMinSum(initialVal);
        uint256 v1 = c.MinSum();

        c.Initialized();

        bool ok;
        try c.SetMinSum(newVal) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 v2 = c.MinSum();

        assertTrue(v2 == v1);
    }
}
